const input = $input.first().json;
const body = input.body || input;

// Validation
const hasFile = !!(body.file_url || body.file_base64);
const hasMistralKey = !!body.mistral_api_key;
const hasAnthropicKey = !!body.api_key || !!body.anthropic_api_key;
const hasOpenAIKey = !!body.openai_api_key;

const errors = [];
if (!hasFile) errors.push('file_url ou file_base64 requis');
if (!hasMistralKey) errors.push('mistral_api_key requis');
if (!hasAnthropicKey) errors.push('api_key (Anthropic) requis');
if (!hasOpenAIKey) errors.push('openai_api_key requis');

// Fonction pour détecter le MIME type depuis les magic bytes base64
function detectMimeFromBase64(base64) {
  const prefix = base64.substring(0, 20);
  if (prefix.startsWith('/9j/')) return 'image/jpeg';
  if (prefix.startsWith('iVBOR')) return 'image/png';
  if (prefix.startsWith('R0lG')) return 'image/gif';
  if (prefix.startsWith('UklGR')) return 'image/webp';
  if (prefix.startsWith('Qk')) return 'image/bmp';
  if (prefix.startsWith('JVBER') || prefix.startsWith('JVBERi')) return 'application/pdf';
  return null;
}

// Fonction pour obtenir le MIME type depuis l'extension
function getMimeFromExtension(ext) {
  const map = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'gif': 'image/gif',
    'webp': 'image/webp', 'bmp': 'image/bmp',
    'tiff': 'image/tiff', 'tif': 'image/tiff',
    'pdf': 'application/pdf'
  };
  return map[(ext || '').toLowerCase()] || null;
}

// Préparer l'URL du fichier avec détection MIME intelligente
let fileUrl = '';
let detectedMime = 'application/pdf';

if (body.file_url) {
  fileUrl = body.file_url;
} else if (body.file_base64) {
  // 1. Essayer depuis file_type param
  if (body.file_type) {
    detectedMime = getMimeFromExtension(body.file_type) || 'application/pdf';
  }
  // 2. Fallback: détecter depuis magic bytes
  if (detectedMime === 'application/pdf') {
    const detected = detectMimeFromBase64(body.file_base64);
    if (detected) detectedMime = detected;
  }
  fileUrl = 'data:' + detectedMime + ';base64,' + body.file_base64;
}

// Job ID
const jobId = 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    jobId: jobId,
    fileUrl: fileUrl,
    detectedMime: detectedMime,
    sourceLanguage: body.source_language || 'auto',
    targetLanguage: body.target_language || 'fr',
    mistralApiKey: body.mistral_api_key,
    anthropicApiKey: body.api_key || body.anthropic_api_key,
    openaiApiKey: body.openai_api_key,
    callbackUrl: body.callback_url || null
  }
}];

