const input = $input.first().json;
const prevData = $('Validation').first().json;

const data = input.body || input;
const apiJobId = data.job_id || prevData.jobId;

return [{
  json: {
    ...prevData,
    jobId: apiJobId
  }
}];

const input = $input.first().json;
const prevData = $('Extract Job ID').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier erreur OCR
if (statusCode >= 400) {
  return [{
    json: {
      ...prevData,
      ocrSuccess: false,
      ocrError: data.message || data.error?.message || 'Mistral API error: ' + statusCode
    }
  }];
}

const ocrText = data.choices?.[0]?.message?.content || '';

if (!ocrText) {
  return [{
    json: {
      ...prevData,
      ocrSuccess: false,
      ocrError: 'OCR returned empty content'
    }
  }];
}

return [{
  json: {
    ...prevData,
    ocrText: ocrText,
    ocrSuccess: true,
    workerPayload: {
      job_id: prevData.jobId,
      text: ocrText,
      source_language: prevData.sourceLanguage === 'auto' ? 'he' : prevData.sourceLanguage,
      target_language: prevData.targetLanguage,
      api_key: prevData.anthropicApiKey,
      openai_api_key: prevData.openaiApiKey,
      job_type: 'pdf_translation',
      metadata: {
        source: 'pdf_layout_translator',
        ocr_model: 'pixtral-12b-2409'
      }
    }
  }
}];

// Le worker gère la traduction et met à jour le job
const prevData = $('Extract OCR + Prepare Worker').first().json;

console.log('PDF Translation job dispatched:', prevData.jobId);

return [{
  json: {
    jobId: prevData.jobId,
    status: 'processing',
    ocrCompleted: true,
    translationStarted: true
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

